"""Runtime helper for outgoing-text hooks."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Mapping, Optional, cast

from rasa.mantle.content.responses import ResponseButton
from rasa.mantle.hooks.constants import POINT_OUTGOING_TEXT
from rasa.mantle.hooks.exceptions import HookRejection
from rasa.mantle.hooks.payloads import ChannelInfo, OutgoingTextPayload
from rasa.mantle.hooks.registry import HookRegistry
from rasa.mantle.hooks.runner import run_modify, run_observers


@dataclass(frozen=True)
class OutgoingTextDecision:
    """Result of applying outgoing-text hooks to one completed utterance."""

    text: str
    rejected: bool = False
    response_message: Optional[str] = None


@dataclass(frozen=True)
class OutgoingRejectionFallback:
    """User-visible text after ``HookRejection`` at the outgoing-text point."""

    text: str
    buttons: tuple[ResponseButton, ...] = ()
    variant_metadata: Mapping[str, Any] | None = None
    response_name: Optional[str] = None


def has_outgoing_text_hooks(registry: HookRegistry) -> bool:
    """Return whether any outgoing-text observer or modifier is registered."""
    return bool(
        registry.observers(POINT_OUTGOING_TEXT)
        or registry.modifier(POINT_OUTGOING_TEXT) is not None
    )


def has_outgoing_text_modifier(registry: HookRegistry) -> bool:
    """Return whether streamed tokens must be buffered for a modifier."""
    return registry.modifier(POINT_OUTGOING_TEXT) is not None


async def apply_outgoing_text_hooks(
    registry: HookRegistry,
    text: str,
    *,
    sender_id: str,
    channel: ChannelInfo,
    is_voice: bool,
) -> OutgoingTextDecision:
    """Run outgoing hooks once on a completed utterance.

    Rejection is explicit. Unexpected modifier failures, timeouts, and invalid
    return values fail open and preserve the original text.
    """
    if not has_outgoing_text_hooks(registry):
        return OutgoingTextDecision(text=text)

    payload = OutgoingTextPayload(
        sender_id=sender_id,
        channel=channel,
        text=text,
        is_voice=is_voice,
    )
    run_observers(registry, POINT_OUTGOING_TEXT, payload)
    result = await run_modify(registry, POINT_OUTGOING_TEXT, payload)

    if isinstance(result.control_flow, HookRejection):
        return OutgoingTextDecision(
            text=text,
            rejected=True,
            response_message=result.control_flow.response_message,
        )

    modified = cast(OutgoingTextPayload, result.payload)
    return OutgoingTextDecision(text=modified.text)
